/** 7桁の郵便番号（ハイフンなし）から住所を引く */
export function lookupZip(zip7) {
  const z = String(zip7 || '').replace(/[^0-9]/g, '');
  if (z.length !== 7) return null;
  const grp = DB.g[z.slice(0, 3)];
  if (!grp) return null;
  const idx = grp[z.slice(3)];
  if (idx === undefined) return null;
  const [pi, city] = DB.c[idx];
  return { pref: DB.p[pi], city };
}
